Sure! No problem. Let me know if you need additional info. 

By the way, here’s a workaround - it patches xcodeproj with updated path:

```
	func _export_end() -> void:
		if get_export_platform() is EditorExportPlatformIOS:
			var export_dir := _last_export_path.get_base_dir()

			var xcodeproj_dir := ""
			var dir_access := DirAccess.open(export_dir)
			if dir_access:
				dir_access.list_dir_begin()
				var fname := dir_access.get_next()
				while fname != "":
					if fname.ends_with(".xcodeproj"):
						xcodeproj_dir = fname
						break
					fname = dir_access.get_next()
				dir_access.list_dir_end()
			else:
				push_warning("Could not open export directory: %s" % export_dir)
				return

			if xcodeproj_dir == "":
				push_warning("No .xcodeproj found in: %s" % export_dir)
				return

			var pbxproj_path := export_dir.path_join(xcodeproj_dir).path_join("project.pbxproj")

			if not FileAccess.file_exists(pbxproj_path):
				push_warning("project.pbxproj not found at: %s" % pbxproj_path)
				return

			var content := FileAccess.get_file_as_string(pbxproj_path)

			var regex := RegEx.new()
			if regex.compile("[\\w\\-]+/addons/AdvertySDK/bin/ios/AdvertyGodotPlugin\\.a") != OK:
				push_warning("Failed to compile regex.")
				return

			if regex.search(content):
				var bundle_name := xcodeproj_dir.replace(".xcodeproj", "")
				var correct_path := "%s/addons/ExamplePlugin/bin/ios/libExampleGodotPlugin.a" % bundle_name
				content = regex.sub(content, correct_path, true)

				var f := FileAccess.open(pbxproj_path, FileAccess.WRITE)
				f.store_string(content)
				f.close()
